data.input:
const cmds = [
  `find FormalizedSources/AbelianVarieties/Mumford/hgraph/nodes -type f | wc -l`,
  `find FormalizedSources/AbelianVarieties/Mumford/hgraph/nodes -type f -printf '%T@ %p\\n' | sort -nr | head -20`,
  `find FormalizedSources/AbelianVarieties/Mumford/hgraph/edges -type f | wc -l`,
  `find FormalizedSources/AbelianVarieties/Mumford/hgraph -maxdepth 2 -type f -printf '%T@ %p\\n' | sort -nr | head -20`,
  `jq '.metadata // .meta // .stats // empty' .archon-horizon/blueprints/Mumford.json`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

