const cmds = [
  `"$HORIZON_BIN" graph --help`,
  `"$HORIZON_BIN" graph sync --help`,
  `"$HORIZON_BIN" graph -p Mumford sync --help`,
  `"$HORIZON_BIN" graph -p Mumford get decl:Mumford.Uniformization.zsmulDivisionFiberEquivBetween_trans --json | jq '{decl,lean_status,depends_on,depended_on_by,comments,reviews}'`,
  `"$HORIZON_BIN" graph -p Mumford get decl:Mumford.Uniformization.ComplexTorusUniformization.ext --json | jq '{decl,lean_status,depends_on,depended_on_by,comments,reviews}'`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

const cmds = [
  `sed -n '1,160p' FormalizedSources/AbelianVarieties/Mumford/hgraph/config.yaml`,
  `find FormalizedSources/AbelianVarieties/Mumford/hgraph/nodes -type f -name '*.md' -printf '%f\\n' | sort | grep -E '^(185dae4391e4|50cb5c|4c3a|e724|8d102|4cff|9145|a23c|47f4|bd44|e075)'`,
  `for f in 185dae4391e4 50cb5c 4c3a e724ff9b6682 8d10226e4b41 4cff0b5ca584 914536?; do :; done`,
  `"$HORIZON_BIN" graph -p Mumford list --state formalized_open --json`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

const cmds = [
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib.lean`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/lakefile.toml`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/README.md | sed -n '1,220p'`,
  `"$HORIZON_GIT" show HEAD:FormalizedSources/AbelianVarieties/Mumford/MumfordLib.lean | diff -u - FormalizedSources/AbelianVarieties/Mumford/MumfordLib.lean`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

const cmds = [
  `for c in 72c16f0cc9 a9e23b0a41 9024d56887; do echo "=== $c ==="; "$HORIZON_GIT" diff-tree --no-commit-id --name-status -r "$c"; done`,
  `for c in 72c16f0cc9 a9e23b0a41 9024d56887; do echo "=== $c trailers ==="; "$HORIZON_GIT" show -s --format='%(trailers)' "$c"; done`,
  `"$HORIZON_GIT" log --format='%h %s' --all -- .archon-horizon/blueprints/Mumford.json | head -15`,
  `"$HORIZON_GIT" log --format='%h %s' --all -- FormalizedSources/AbelianVarieties/Mumford/MumfordLib/ComplexUniformization.lean | head -10`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

const cmds = [
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib/ThetaNondegenerate.lean | sed -n '1,280p'`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib/ThetaIsotropic.lean | sed -n '1,180p'`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib/Analytic.lean | sed -n '1,260p'`,
  `rg -n -C 5 "character|dual|order square|natCard_eq_square|IsMaximalIsotropic|commutatorPairingRestriction" FormalizedSources/AbelianVarieties/Mumford/MumfordLib`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:40000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

const cmds = [
  `rg -n -C 8 "structure PeriodLatticeQuotient|quotientAddEquiv_mk|quotientAddEquiv" FormalizedSources/AbelianVarieties/Mumford/MumfordLib/Lattice.lean`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib/Lattice.lean | sed -n '1,130p'`,
  `nl -ba FormalizedSources/AbelianVarieties/Mumford/MumfordLib/Uniformization.lean | sed -n '1,120p'`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:18000})));
for(let i=0;i<rs.length;i++)text(`===${i+1}===\n${rs[i].output}`);

